begin;
do $$
declare principal uuid;staff uuid;post uuid;file_id uuid;obj text;version timestamptz;result jsonb;request_id uuid:=gen_random_uuid();visitor uuid:=gen_random_uuid();recipients integer;
begin
 select id into principal from public.cheongla_profiles where role in('owner','english_director','math_director')and approval_status='approved'and membership_state='active'limit 1;
 select id into staff from public.cheongla_profiles where role='manager'and approval_status='approved'and membership_state='active'limit 1;
 assert principal is not null and staff is not null;
 assert not has_function_privilege('anon','public.cheongla_prepare_director_post(uuid,text)','execute'),'anonymous authoring exposed';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 begin perform public.cheongla_prepare_director_post(null,'thoughts');raise exception 'manager can author';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',principal::text,true);
 result:=public.cheongla_prepare_director_post(null,'thoughts');post:=(result->>'id')::uuid;version:=(result->>'updated_at')::timestamptz;
 obj:=post||'/'||gen_random_uuid()||'.png';
 perform set_config('request.jwt.claim.sub',staff::text,true);execute 'set local role authenticated';
 begin insert into storage.objects(bucket_id,name,metadata)values('cheongla-director',obj,'{"size":4,"mimetype":"image/png"}');raise exception 'manager storage upload allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',principal::text,true);execute 'set local role authenticated';
 insert into storage.objects(bucket_id,name,metadata)values('cheongla-director',obj,'{"size":4,"mimetype":"image/png"}');execute 'reset role';
 file_id:=public.cheongla_stage_director_file(post,obj,'검증.png',4);
 execute 'set local role anon';
 assert not exists(select 1 from public.cheongla_director_posts where id=post),'draft publicly visible';
 assert not exists(select 1 from public.cheongla_director_files where id=file_id),'pending attachment publicly visible';
 assert not exists(select 1 from storage.objects where bucket_id='cheongla-director'and name=obj),'pending file downloadable';
 execute 'reset role';
 result:=public.cheongla_save_director_post(post,'검증 공개 글','<script>문자 그대로 표시</script>','published',version,array[file_id]);
 version:=(result->>'updated_at')::timestamptz;
 assert exists(select 1 from cheongla_private.director_post_history where post_id=post),'revision history missing';
 select count(*)into recipients from public.cheongla_profiles where approval_status='approved'and membership_state='active';
 assert (select count(*)from public.cheongla_notifications where source_kind='director_post'and source_id=post)=recipients,'publication inbox recipients missing';
 assert cheongla_private.can_read_notification('director_post',post,null),'published notification unreadable';
 execute 'set local role anon';
 assert exists(select 1 from public.cheongla_director_posts where id=post),'public reading blocked';
 assert exists(select 1 from public.cheongla_director_files where id=file_id),'published file metadata blocked';
 assert exists(select 1 from storage.objects where bucket_id='cheongla-director'and name=obj),'published file signing blocked';
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 begin perform public.cheongla_save_director_post(post,'위조','위조','published',version,'{}');raise exception 'manager can edit';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',principal::text,true);
 begin perform public.cheongla_save_director_post(post,'오래된 수정','내용','published',null,'{}');raise exception 'stale save allowed';exception when raise_exception then if sqlerrm='stale save allowed'then raise;end if;end;
 begin perform public.cheongla_stage_director_file(post,obj,'악성.html',4);raise exception 'HTML file allowed';exception when raise_exception then if sqlerrm='HTML file allowed'then raise;end if;end;
 perform public.cheongla_save_director_post(post,'비공개 검증','비공개','draft',version,'{}');
 assert not cheongla_private.can_read_notification('director_post',post,null),'draft notification leaks';
 execute 'set local role anon';assert not exists(select 1 from storage.objects where bucket_id='cheongla-director'and name=obj),'unpublished file still readable';execute 'reset role';
 perform public.cheongla_request_account_help_v2(visitor,request_id,'id','복구검증','01000000995','student','','','','검증고등학교');
 assert exists(select 1 from cheongla_private.account_help_requests where request_token=request_id and school_name='검증고등학교'),'school not saved';
end $$;
rollback;
select 'PASS: principal-only writing; drafts/pending files private; published posts/files readable; school recovery; revision/conflict/file validation; inbox notifications generated; all fixtures rolled back' as result;
